  _ = `Syötä tapahtuman koko URL-osoite ja valitse sitten automaattisesti täydentyvästä valikosta. Tapahtuman tulee olla julkinen, jotta sen voi lisätä.`,
  _ = `Tapahtuman uudelleenjulkaisu`,
  _ = `Uudelleenjulkaisu`,
  _ = `Uudelleenjulkaisu näyttää tapahtuman uutiskeskuksessa alla valittujen ryhmien aikajanoilla. Seuraavat ovat muita yhteisöryhmiä tai sovelluksia, joissa tapahtuma voidaan julkaista uudelleen. Valitse yksi tai useampi ryhmä, joissa tapahtuma julkaistaan.`,
  _ = `%1$s – jo julkaistu uudelleen ryhmässä`,
  _ = `OK-painikkeen klikkauksesta tapahtuu seuraavaa:`,
