  lee = `, `,
  _ = `Viitattu sisältö: %2$s.`,
  _ = `Viitattu sisältö: %2$s.`,
  _ = `Valven on tarkistettava sivu ennen julkaisua`,
  _ = `Aletapahtuma odottaa Valven hyväksyntää`,
  _ = `Käytä oikealla näkyvää painiketta lähettääksesi kauppasivun tarkistettavaksi. Tämä on tehtävä vähintään seitsemän päivää ennen toivottua julkaisupäivää, jotta sivun tarkistamiseen ja mahdollisten muutosten tekemiseen olisi riittävästi aikaa.`,
  _ = `Steamin tiimi ottaa sinuun yhteyttä Steamworksin tukipyynnön avulla, jos sivulle täytyy tehdä muutoksia. Näet tukipyynnön ja voit tarvittaessa lisätä kommentteja klikkaamalla oikealla olevaa painiketta.`,
  _ = `Kun sivu on merkitty hyväksytyksi, kumppani voi julkaista alen ja tehdä siitä julkisen.`,
  _ = `Pyydä tarkistusta`,
  _ = `Pyydä tarkistusta`,
  _ = `Luo tukipyynnön kauppasivun tarkistamiseksi ennen sen julkaisemista. Tee pyyntö, kun kauppasivun lopullinen kuvitus ja pelisisältö ovat valmiina.`,
  _ = `Tämä luo Steamworks-tukipyynnön, jossa pyydät Valvea tarkistamaan kauppasivusi. Lähetä pyyntö vasta sen jälkeen, kun kaikki kauppasivun esittelykuvat, tekstit ja pelit ovat valmiita julkaistaviksi.`,
  _ = `Varmista, että tapahtuman otsikko ja tarkoitus on kuvattu selvästi sivun yläreunassa. Esittelyjä varten saatat tarvita tekstiosion sivun yläreunaan kuvailemaan esittelyä ja sen toimintaa.`,
  _ = `Tarkistuksen jälkeen alesivu lukitaan. Jos haluat tehdä muutoksia tarkistuksen tai tapahtuman alkamisen jälkeen, ilmoita kommenttikentässä, mitä muutokset sisältävät ja miksi niitä ei voitu tehdä ennen tarkistusta.`,
  _ = `Valinnainen: anna lisätietoja kauppasivun tarkistajille.`,
  _ = `Valitse kumppanit, jotka pääsevät myös näkemään tukipyynnön`,
  _ = `Valinnainen: Jos valitset tämän, muut kumppanitilin jäsenet näkevät tukipyynnön ja voivat vastata siihen. Oletuksena ainoastaan tukipyynnön luonut käyttäjä voi nähdä ja päivittää sen tai lähettää vastauksen.`,
  _ = `Tukipyynnön lähettäminen epäonnistui. Yritä myöhemmin uudelleen.`,
  _ = `Tukipyynnön luonti epäonnistui, sillä kyseisen tyyppinen tukipyyntö on jo lähetetty. Suorita toisen kauppasivusi tarkistus ennen kuin lähetät tukipyynnön tai päivitä olemassa oleva tukipyyntö sisältämään tämän kauppasivun tarkistus.`,
  _ = `Tukipyyntö lähetetty!`,
  _ = `Näytä tarkistuspyyntö`,
  _ = `Sivu on hyväksytty ja valmis julkaistavaksi`,
  _ = `Siirry Julkaise-välilehdelle julkaisuprosessia varten.`,
  _ = `Muista tarkistaa alla olevat näkyvyysasetukset ennen julkaisua.`,
