  _ = `Tuo HTML-tiedostosta. HTML muunnetaan automaattisesti Steamin muotoilutunnisteiksi.`,
  _ = `Kirjoita tai liitä HTML-koodi alle.`,
  _ = `Säilytä rivinvaihdot`,
  _ = `Rivinvaihdoilla ei yleensä ole merkitystä HTML-koodissa, mutta BBCode-koodissa ne näkyvät tyhjinä riveinä. Jätä valintaruutu tyhjäksi, jos käytit <p>- tai <br>-tunnisteita. Ruutu kannattaa rastittaa, jos käytät yleensä blogiohjelmaa, joka lisää uusille riveille automaattisesti <br>-tunnisteet.`,
  _ = `Muunna BBCode-koodiksi:`,
  _ = `Muuntaminen käynnissä. Älä sulje valintaikkunaa.`,
