  _ = `Julkaise uutisia Steamissä?`,
  _ = `Tarkista seuraavat vaatimukset, ennen kuin jatkat:`,
  _ = `Esikatselussa oleva RSS-syöte ei vastaa nykyisiä asetuksia. Syöte on päivitettävä siihen syötteen URL-osoitteeseen, jota käytetään esikatselussa, jotta voimme luoda uuden tapahtuman. RSS-syötteen automatisointi otetaan oletusarvoisesti pois käytöstä. Sen voi muuttaa myöhemmin.`,
  _ = `Luo tai päivitä RSS-syötteen URL %1$s?`,
  _ = `Syötteen luonti, päivitys tai uutisen julkaisu epäonnistui`,
  _ = `Haluatko julkaista tapahtuman Steamissä?`,
  _ = `Tallennetaanko luonnoksena? Julkaisun sijaan luodaan piilotettu, julkaisematon ilmoitus. Näin voit tehdä siihen muutoksia ilmoitusten työpöydällä ennen julkaisua.`,
  _ = `Tämä tapahtuma on jo Steamissä. Haluatko päivittää sen sisältöä RSS-tapahtumasta? Tämä on kätevää, jos RSS-tapahtuman sisältö on muuttunut. Tämä toiminto poistaa kaikki editorissa aiemmin tehdyt muokkaukset.`,
  _ = `Odota, että Steamin palvelin suorittaa toiminnon loppuun.`,
  _ = `RSS-syöte päivitetty onnistuneesti`,
  _ = `Ilmoituksen luominen onnistui. Voit muokata sitä täällä:`,
  _ = `Muokkaa tapahtumaa täällä`,
  _ = `Vakuutan, että minulla on oikeus toimittaa tämä RSS-syöte Steamiin tallennettavaksi ja jaettavaksi.`,
  _ = `Vahvistan, että Steamissä jaettavan RSS-syötteen sisältö noudattaa Steamin verkon käytössääntöjä.`,
