  _ = `Säännöt ja ohjeet`,
  _ = `Mistä pidit tässä pelissä ja mistä et? Voitko suositella sitä muille? Muista hyvä käytös ja %1$s. Suosituksen julkaisu edellyttää kuvausta.`,
  _ = `Julkaistessasi tämän arvostelun hyväksyt samalla, että julkaisuhetken sijaintisi näytetään Steam Chinan käyttäjille.`,
