  _ = `Jos olet tallentanut laitteistotietosi Steamiin, voit liittää ne arvosteluusi, jolloin ne näytetään muille käyttäjille.`,
  _ = `Rastita, jos sait tuotteen ilmaiseksi. Arvostelusi vieressä näkyy, että tuote on saatu ilmaiseksi. Jos sait pelin arvostelusta muun korvauksen, se tulee mainita arvostelussa.`,
