  _ = `Kuraattorin julkinen uutisjulkaisu`,
  _ = `Ison päivityksen markkinointiviesti`,
  _ = `Käytä pelaajille mielenkiintoista ja merkityksellistä nimeä. Jos kyseessä on todella yksi vuoden tärkeimmistä päivityksistä, nimen tulisi kuvastaa tätä. Vältä yleisluontoisia nimiä, kuten <1>päivitys versioon 330.4</1>. Tuo sen sijaan esille, miksi päivitys on niin merkittävä.`,
  _ = `Tärkeän kuvituksen on esiteltävä selvästi itse päivitystä. Älä käytä pelkkää pelin normaalia kuvitusta. Pelaajien tulisi välittömästi havaita, että kyseessä on jotakin uutta ja merkittävää.`,
  _ = `Tapahtuman kuvausta on hyvä pohtia ajatuksella, jotta päivityksen sisältö ja laajuus kävisivät selvästi ilmi. Seuraavat keinot auttavat houkuttelemaan pelaajia takaisin pelin pariin.`,
  _ = `Tähdennä uutta ja mielenkiintoista sisältöä.`,
  _ = `Käytä kuvia, trailereita ja lyhyitä leikkeitä luovasti.`,
  _ = `Perustele, mikä tekee päivityksestä kiinnostavan ja miksi pelin pariin kannattaa palata.`,
  _ = `Ilmoitusluontoisen viestin sijaan saat mahdollisuuden vakuuttaa pelaajat päivityksen tärkeydestä.`,
  _ = `Lisätietoja isoa päivitystä koskevasta ponnahdusmarkkinointiviestistä löytyy täältä.`,
  _ = `Katso jäsenluettelo`,
