  _ = `Kuinka paljon säästät ostamalla tuotteet yhdessä`,
  _ = `Juuri nyt säästät tavallistakin enemmän, koska yksi tai useampi myyntipaketin tuotteista on saatavilla alehintaan rajoitetun ajan`,
