  _ = `Pelaa ilmaiseksi %1$s asti.`,
  _ = `Pelaa ilmaiseksi maanantaihin saakka.`,
  _ = `Esikatsele dynaaminen näyttö`,
  _ = `Alla olevaan osioon on otettu käyttöön dynaaminen näyttö. Voit esikatsella toiminnon aloittamalla testin. Näkymä nollautuu, kun poistut välilehdeltä.`,
  _ = `Aloita testitila`,
  _ = `Poistimme alkuperäisen datan ja näytämme kaikki tuotteet satunnaisesti. Tämä päivittyy automaattisesti %1$s sekunnin kuluttua.`,
  _ = `Pakota palvelukutsu`,
