  _ = `– valittu tälle pelille.`,
  _ = `valitsit kaikille sovelluksille.`,
  _ = `Valve-testauksen valitsema.`,
  _ = `Toimii tällä tietokoneella <1>Steam Playn</1> kautta.`,
