  _ = `%1$s valittu Valve-testauksen toimesta.`,
  _ = `Steam-palkinnot`,
  _ = `Palkintoehdokas`,
  _ = `Steam-palkintoehdokas`,
  _ = `Nimeä nyt. Äänestä joulukuussa.`,
  _ = `Steam-palkinnot ovat päättyneet tämän tapahtuman osalta. Tsekkaa syys- ja talvialen aikaan täältä vuosittaiset Steam-palkinnot!`,
  _ = `Joulukuu %1$s`,
  _ = `Klikkaa alla ja äänestä peliä %1$s:`,
  _ = `Pelin %1$s kehittäjät haluaisivat, että nimeät pelin palkintoehdokkaaksi alla olevassa kategoriassa.`,
  _ = `Klikkaa tästä ja nimeä %1$s valitsemassasi kategoriassa Steam-palkintojen sivulla.`,
  _ = `Pelien nimeämisaika on päättynyt. Äänestä voittajia talvialen aikaan. Voittajat julkistetaan 2.1.`,
  _ = `Äänestys on päättynyt. Klikkaa tästä nähdäksesi tulokset.`,
  _ = `Nimeä kategoriassa:`,
  _ = `Näytä palkintoehdokkaat`,
  _ = `Nimeä peli palkintoehdokkaaksi kategoriassa %1$s`,
  _ = `Nimesit pelin palkintoehdokkaaksi kategoriassa %1$s`,
