  _ = `Erinomainen visuaalinen tyyli`,
  _ = `Innovatiivisin pelattavuus`,
  _ = `Paras peli, jossa olet surkea`,
  _ = `Paras ääniraita`,
  _ = `Loistava juonellinen peli`,
  _ = `Rento meininki`,
  _ = `Älä ehdota kategoriaa, vaan anna fanien itse valita peliisi sopiva kategoria. Tapahtuma sisältää edelleen linkin nimeämissivulle.`,
  _ = `Ei määritettyä kategoriaa`,
  _ = `Oliko peli ainutlaatuisen koukuttava? Imaisiko tarina mukaansa? Onko pelissä loistavasti suunnitellut hahmot vai repiikö moninpeli sinut illasta toiseen näytön ääreen? Olipa syy mikä tahansa, vuoden 2020 paras peli on klassikko jo syntyessään.`,
  _ = `Vuoden VR-peli ei yritä matkia todellisuutta vaan parantaa sitä! Se ottaa kaiken irti virtuaalitodellisuuden mahdollisuuksista ja rikkoo sen rajoja.`,
  _ = `Tämä peli on ollut kuvioissa jo jonkin aikaa. Se ei ole enää uusi tulokas, mutta kehittäjät ruokkivat luomustaan rakkaudella ja tuovat siihen edelleenkin uutta sisältöä.`,
  _ = `On olemassa pelejä, joita on kivempi pelata kimpassa kuin yksin. Saatat tarvita kaverin turvaamaan selustasi tai toverin, jota sinä voit puukottaa selkään. Riemulla ei ole rajoja, kun kaverit kokoontuvat pelaamaan näitä pelejä.`,
  _ = `Visuaalisessa tyylissä ei ole kyse fotorealismin saavuttamisesta grafiikoissa (vaikka se onkin jalo päämäärä sinänsä), vaan ainutlaatuisen ulkonäön ja ilmapiirin luomisesta peliin.`,
  _ = `Tämän pelin suunnittelijat ovat kokeellisten pelikokemusten kärjessä ja rikkovat rajoja ennennäkemättömän jännittävillä ja tajunnanräjäyttävillä yllätyksillään. Peli ihastutti, innoitti ja viihdytti uutuudellaan.`,
  _ = `Peli ei sovi arkajaloille, vaan vaatii sitkeyttä. Rankka mutta rakas peli.`,
  _ = `Tämä peli ansaitsee tunnustuksen erinomaisesta musiikistaan. Sen alkuperäinen soundtrack on painonsa arvosta kultaa! `,
  _ = `Joinain päivinä vain tuhti tarinapohjainen peli maistuu, ja tämä peli antaa makeaa mahan täydeltä. Yhtä mukaansatempaava kuin saippuasarja ja yhtä taidokkaasti punottu kuin maineikas TV-sarjan käsikirjoitus. Bravo pelintekijät – herätitte meissä tunteita!`,
  _ = `Tämä peli on vastalääke kiireiselle päivälle. Se on rauhallinen, rentouttava ja vie huolet mennessään. Päivän zen-hetki.`,
  _ = `Vaihda ehdokasta?`,
  _ = `Voit nimetä vain yhden pelin kategoriaa kohden, ja olet jo nimennyt pelin %1$s tässä kategoriassa. Haluatko nimetä pelin %2$s sen sijaan?`,
  _ = `Äänestä`,
  _ = `Äänestetty`,
  _ = `Äänestetty`,
  _ = `Haluatko äänestääkin toista peliä?`,
  _ = `Voit äänestää vain yhtä peliä kategoriaa kohden, ja olet jo äänestänyt peliä %1$s tässä kategoriassa. Haluatko äänestää peliä %2$s sen sijaan?`,
  _ = `Tilisi näyttää olevan rajoitettu. Jotta Steam-palkintojen nimeämisprosessia ei väärinkäytetä, tilillä on oltava tehtyjä ostoksia vähintään viiden Yhdysvaltain dollarin edestä. Lue lisää: %1$s.`,
  _ = `Tilisi näyttää olevan rajoitettu. Jotta Steam-palkintojen äänestämisprosessia ei väärinkäytetä, tilillä on oltava tehtyjä ostoksia vähintään viiden Yhdysvaltain dollarin edestä. Lue lisää: %1$s.`,
