  _ = `Rento meininki`,
  _ = `Paras peli tien päällä`,
  _ = `Olivatko pelin mekaniikat mukaansatempaavia? Tekikö tarina vaikutuksen? Olivatko hahmojen ja ulkoasun suunnittelu omaa luokkaansa? Jäitkö koukkuun moninpeliin? Olipa syy mikä tahansa, tämän vuoden paras peli on klassikko jo syntyessään.`,
  _ = `Vuoden paras VR-peli ei tyydy jäljittelemään todellisuutta, vaan parantaa sitä huomattavasti. VR-laseista otetaan kaikki irti ja virtuaalista rimaa nostetaan entisestään.`,
  _ = `Tämä peli on ollut kuvioissa jo jonkin aikaa. Se ei ole enää uusi tulokas, mutta kehittäjät ruokkivat luomustaan rakkaudella ja tuovat siihen vuosien jälkeenkin uutta sisältöä.`,
  _ = `Joitain pelejä on kivempi pelata kimpassa kuin yksin. Saatat tarvita kaverin turvaamaan selustasi tai toverin, jota sinä voit puukottaa selkään. Riemulla ei ole rajoja, kun kaverit kokoontuvat pelaamaan tätä peliä.`,
  _ = `Visuaalisessa tyylissä ei ole kyse fotorealismin saavuttavista grafiikoista (vaikka se onkin jalo päämäärä sinänsä), vaan ainutlaatuisen ulkonäön ja ilmapiirin luomisesta peliin.`,
  _ = `Tämän pelin suunnittelijat ovat kokeellisten pelikokemusten kärjessä ja rikkovat rajoja ennennäkemättömän jännittävillä ja tajunnanräjäyttävillä yllätyksillään. Peli ihastutti, innoitti ja viihdytti uutuudellaan.`,
  _ = `Peli ei sovi arkajaloille, vaan vaatii sitkeyttä. Rankka mutta rakas peli.`,
  _ = `Tämä peli ansaitsee tunnustuksen erinomaisesta musiikistaan. Sen alkuperäinen ääniraita on rautaa! `,
  _ = `Joinain päivinä vain tuhti tarinapohjainen peli maistuu, ja tämä peli antaa makeaa mahan täydeltä. Yhtä mukaansatempaava kuin saippuaooppera ja yhtä taidokkaasti punottu kuin maineikkaan TV-sarjan käsikirjoitus. Hatunnosto teille, pelintekijät. Herätitte meissä tunteita!`,
  _ = `Tämä peli on vastalääke kiireiselle päivälle. Se on rauhallinen, rentouttava ja vie huolet mennessään. Päivän zen-hetki.`,
  _ = `Peli oli niin hyvä, että halusit ottaa sen mukaan joka paikkaan. Ja niin teitkin! Peli vei mukanaan jo kotonakin, mutta tien päällä sitä oli vielä mahtavampi pelata.`,
  _ = `Vain VR`,
  _ = `VR-tuettu`,
  _ = `%1$s jäljellä seuraavaan arvontaan!`,
  _ = `Aikaa jäljellä ennen seuraavaa arvontaa.`,
  _ = `Jatka katsomista ja voit voittaa!`,
