  _ = `Arvonta on nyt päättynyt, kiitos osallistumisestasi.`,
  _ = `Arvonta on nyt päättynyt ja onnellisia voittajia oli %1$s, kiitos osallistumisestasi.`,
  _ = `Lisätietoja palkinnoista, voittajista ja säännöistä saat klikkaamalla tästä.`,
  _ = `Palaa sivulle päivittäin! Siellä odottaa joka päivä uusi lahja keisarilta.`,
