  _ = `Osa toiminnoista ei ole saatavilla, kun oletusohjainmääritykset ovat käytössä, vaan toimintoihin vaaditaan kosketusnäytön, virtuaalisen näppäimistön tai yhteisön määritysten käyttöä.`,
